const fs = require("fs");
const path = require("path");

function walk(dir, exts, out) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full, exts, out);
        else if (exts.includes(path.extname(entry.name))) out.push(full);
    }
}

const files = [];
walk(path.join(__dirname, "src"), [".ts", ".html"], files);

// Tag-aware: matches an opening tag for app-pill / app-fancy-pill / app-status-pill
// (not app-pill-legacy / app-pill-tray), quote-aware so '>' inside attribute
// expressions doesn't terminate the tag early.
const tagRe = /<app-(pill|fancy-pill|status-pill)(?![\w-])((?:"[^"]*"|'[^']*'|[^"'>])*?)(\/?)>/g;

let totalFiles = 0;
let totalReplacements = 0;

for (const file of files) {
    const original = fs.readFileSync(file, "utf8");
    let replacementsInFile = 0;
    const updated = original.replace(tagRe, (match, tagName, attrs, selfClose) => {
        const newAttrs = attrs.replace(/\bdisableTooltip\b/g, () => {
            replacementsInFile++;
            return "hideHint";
        });
        return `<app-${tagName}${newAttrs}${selfClose}>`;
    });
    if (replacementsInFile > 0) {
        fs.writeFileSync(file, updated, "utf8");
        totalFiles++;
        totalReplacements += replacementsInFile;
        console.log(`${path.relative(__dirname, file)}: ${replacementsInFile}`);
    }
}

console.log(`\nTotal: ${totalReplacements} replacements in ${totalFiles} files`);

