import { ChangeDetectionStrategy, Component, viewChildren } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-105",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent ],
    templateUrl: "./feature-105.component.html"
})
export class Feature105Component {
    isActive = false;
    count = 0;
    title = "Title 105";
    statusVariant: PillVariant = "success";

    private readonly pills = viewChildren(PillComponent);

    quietPills(): number {
        return this.pills().filter(pill => pill.hideHint()).length;
    }
}
